#include <iostream>
#include <string>

int main() {
    std::string data;
    std::getline(std::cin, data);
    int evenCount = 0;
    for (size_t index = 0; index < data.length(); ++index) {
        int segmentSize = 1;
        while (index + 1 < data.length() && data[index] == data[index + 1]) {
            segmentSize++;
            index++;
        }
        if (segmentSize % 2 == 0) {
            evenCount++;
        }
    }
    std::cout << evenCount << std::endl;
    return 0;
}
